/* Astral Glassmorphism: frosted glass input, bubble and sidebar with a soft starlight glow, all from the palette. Pairs with any Canvas FX theme, made for Astral Projection. */
:root {
	--astral-glass: color-mix(in oklab, var(--color-gray-50) 60%, transparent);
	--astral-sidebar: color-mix(in oklab, var(--color-gray-50) 66%, transparent);
	--astral-bubble: color-mix(in oklab, var(--color-gray-200) 55%, transparent);
	--astral-line: color-mix(in oklab, var(--color-gray-500) 28%, transparent);
	--astral-glow: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--astral-star: var(--color-gray-700);
	--astral-focus: color-mix(in oklab, var(--color-gray-500) 55%, transparent);
}
html.dark {
	--astral-glass: color-mix(in oklab, var(--color-gray-900) 55%, transparent);
	--astral-sidebar: color-mix(in oklab, var(--color-gray-950) 62%, transparent);
	--astral-bubble: color-mix(in oklab, var(--color-gray-700) 40%, transparent);
	--astral-line: color-mix(in oklab, var(--color-gray-300) 20%, transparent);
	--astral-glow: color-mix(in oklab, var(--color-gray-300) 30%, transparent);
	--astral-star: var(--color-gray-200);
	--astral-focus: color-mix(in oklab, var(--color-gray-300) 50%, transparent);
}

#message-input-container {
	background-color: var(--astral-glass) !important;
	border-color: var(--astral-line);
	backdrop-filter: blur(16px) saturate(1.3);
	transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
#message-input-container:focus-within {
	border-color: var(--astral-focus);
	box-shadow: 0 0 24px var(--astral-glow);
}
.chat-user .rounded-3xl {
	background-color: var(--astral-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--astral-line);
}
#sidebar {
	background-color: var(--astral-sidebar) !important;
	backdrop-filter: blur(20px) saturate(1.2);
	border-inline-end: 1px solid var(--astral-line);
}
#sidebar-chat-item.selected {
	box-shadow: inset 0 0 0 1px var(--astral-line);
}
#send-message-button:enabled {
	box-shadow: 0 0 14px var(--astral-glow);
}
.markdown-prose :is(h1, h2, h3, h4) {
	color: var(--astral-star);
	text-shadow: 0 0 16px var(--astral-glow);
}
::selection {
	background-color: var(--astral-glow);
}
html {
	scrollbar-color: var(--astral-line) transparent;
}

/* Font Menu: switch Open WebUI's interface font to a system font stack by editing one line; nothing downloads. Pairs with any theme (paste it into each mode you use). */
:root {
	/* The menu: system font stacks (after modernfontstacks.com). Each lists look-alike fonts that ship with Windows, macOS, Linux or Android, then a generic family. */
	--stack-system: system-ui, sans-serif;
	--stack-humanist: Seravek, "Gill Sans Nova", Ubuntu, Calibri, "DejaVu Sans", source-sans-pro, sans-serif;
	--stack-geometric: Avenir, Montserrat, Corbel, "URW Gothic", source-sans-pro, sans-serif;
	--stack-classical: Optima, Candara, "Noto Sans", source-sans-pro, sans-serif;
	--stack-grotesque: Inter, Roboto, "Helvetica Neue", "Arial Nova", "Nimbus Sans", Arial, sans-serif;
	--stack-rounded: ui-rounded, "Hiragino Maru Gothic ProN", Quicksand, Comfortaa, Manjari, "Arial Rounded MT", "Arial Rounded MT Bold", Calibri, source-sans-pro, sans-serif;
	--stack-industrial: Bahnschrift, "DIN Alternate", "Franklin Gothic Medium", "Nimbus Sans Narrow", sans-serif-condensed, sans-serif;
	--stack-transitional: Charter, "Bitstream Charter", "Sitka Text", Cambria, serif;
	--stack-old-style: "Iowan Old Style", "Palatino Linotype", "URW Palladio L", P052, serif;
	--stack-mono: ui-monospace, "Cascadia Code", "Source Code Pro", Menlo, Consolas, "DejaVu Sans Mono", monospace;

	/* Your pick: change this one line to any stack above. */
	--font-pick: var(--stack-humanist);

	/* A font typed in Settings > Interface > Font Family still wins over the pick. */
	--font-sans: var(--app-font-family, var(--font-pick)), "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji";
}

/* Matrix Colors: phosphor-green accents, a faint green grid behind the chat and monospace replies, in fixed greens that read on light and dark palettes. Pairs with Matrix Rain. */
:root {
	--mx-green: #0a7d2c;
	--mx-on-green: #ffffff;
	--mx-line: rgb(10 125 44 / 0.3);
	--mx-wash: rgb(10 125 44 / 0.1);
	--mx-grid: rgb(10 125 44 / 0.07);
}
html.dark {
	--mx-green: #3dff6e;
	--mx-on-green: #021a07;
	--mx-line: rgb(61 255 110 / 0.28);
	--mx-wash: rgb(61 255 110 / 0.09);
	--mx-grid: rgb(61 255 110 / 0.05);
}

#chat-container {
	background-image: linear-gradient(var(--mx-grid) 1px, transparent 1px), linear-gradient(90deg, var(--mx-grid) 1px, transparent 1px);
	background-size: 24px 24px;
}
#message-input-container {
	border-color: var(--mx-line);
	caret-color: var(--mx-green);
}
#message-input-container:focus-within {
	border-color: var(--mx-green);
	box-shadow: 0 0 18px var(--mx-wash);
}
.chat-user .rounded-3xl {
	background-color: var(--mx-wash) !important;
	box-shadow: inset 0 0 0 1px var(--mx-line);
}
#sidebar-chat-item.selected {
	background-color: var(--mx-wash);
	box-shadow: inset 2px 0 0 var(--mx-green);
}
#send-message-button:enabled {
	background-color: var(--mx-green);
	color: var(--mx-on-green);
}
.markdown-prose {
	font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
	--tw-prose-headings: var(--mx-green);
	--tw-prose-links: var(--mx-green);
	--tw-prose-code: var(--mx-green);
	--tw-prose-bullets: var(--mx-green);
}
::selection {
	background-color: var(--mx-line);
}
html {
	scrollbar-color: var(--mx-line) transparent;
}

/* Ocean Waves companion: glass input and bubble, caustic hairlines and crest-colored links, in the palette's colors, as Ocean Waves takes them. Pairs with the Ocean Waves Canvas FX. */
:root {
	/* Light modes: the same water, read from above the surface. */
	--ow-glass: color-mix(in oklab, var(--color-gray-50) 60%, transparent);
	--ow-bubble: color-mix(in oklab, var(--color-gray-200) 55%, transparent);
	--ow-line: color-mix(in oklab, var(--color-gray-500) 25%, transparent);
	--ow-glow: color-mix(in oklab, var(--color-gray-600) 55%, transparent);
	--ow-crest: var(--color-gray-700);
	--ow-wash: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
}
html.dark {
	--ow-glass: color-mix(in oklab, var(--color-gray-900) 35%, transparent);
	--ow-bubble: color-mix(in oklab, var(--color-gray-700) 45%, transparent);
	--ow-line: color-mix(in oklab, var(--color-gray-300) 20%, transparent);
	--ow-glow: color-mix(in oklab, var(--color-gray-300) 60%, transparent);
	--ow-crest: var(--color-gray-200);
	--ow-wash: color-mix(in oklab, var(--color-gray-300) 13%, transparent);
}

/* The composer reads as glass resting on the surface. */
#message-input-container {
	background-color: var(--ow-glass) !important;
	backdrop-filter: blur(14px) saturate(1.2);
}
#message-input-container:not(:hover):not(:focus-within) {
	border-color: var(--ow-line);
}
#message-input-container:focus-within {
	border-color: var(--ow-glow);
}
.chat-user .rounded-3xl {
	background-color: var(--ow-bubble) !important;
	backdrop-filter: blur(10px);
}

/* Sidebar: a caustic edge, and the open chat lit like a crest. */
#sidebar {
	border-inline-end: 1px solid var(--ow-line);
}
#sidebar-chat-item.selected {
	background-color: var(--ow-wash);
	box-shadow: inset 2px 0 0 var(--ow-glow);
}

/* Links take the crest color, inline code sits in shallow water. */
.markdown-prose a {
	color: var(--ow-crest);
	text-decoration-color: var(--ow-line);
}
.markdown-prose .codespan {
	background-color: var(--ow-wash);
}
.markdown-prose hr {
	border-color: var(--ow-line);
}

/* Selection, focus and scrollbars in caustic light instead of Tailwind blue and graphite. */
::selection {
	background-color: var(--ow-wash);
}
.app :focus-visible {
	outline-color: var(--ow-glow);
}
html {
	scrollbar-color: var(--ow-line) transparent;
}

/* Retro Terminal CRT: still scanlines over the app, a phosphor glow on monospace replies and a lit input, tinted by the palette. Pairs with Retro Terminal, Matrix Rain or any green or amber theme. */
:root {
	--crt-phosphor: var(--color-gray-800);
	--crt-bright: var(--color-gray-900);
	--crt-glow: transparent;
	--crt-line: color-mix(in oklab, var(--color-gray-600) 35%, transparent);
	--crt-wash: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
	--crt-scan: rgb(0 0 0 / 0.035);
}
html.dark {
	--crt-phosphor: var(--color-gray-200);
	--crt-bright: var(--color-gray-50);
	--crt-glow: color-mix(in oklab, var(--color-gray-300) 45%, transparent);
	--crt-line: color-mix(in oklab, var(--color-gray-400) 35%, transparent);
	--crt-wash: color-mix(in oklab, var(--color-gray-400) 12%, transparent);
	--crt-scan: rgb(0 0 0 / 0.16);
}

/* Scanlines sit over the sidebar and chat, under menus and dialogs, and never move. */
.app::after {
	content: "";
	position: fixed;
	inset: 0;
	z-index: 40;
	pointer-events: none;
	background-image: repeating-linear-gradient(to bottom, var(--crt-scan) 0 1px, transparent 1px 3px);
}
.markdown-prose {
	font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
	text-shadow: 0 0 6px var(--crt-glow);
	--tw-prose-body: var(--crt-phosphor);
	--tw-prose-headings: var(--crt-bright);
	--tw-prose-bold: var(--crt-bright);
	--tw-prose-links: var(--crt-bright);
}
#message-input-container {
	border-color: var(--crt-line);
	caret-color: var(--crt-bright);
}
#message-input-container:focus-within {
	box-shadow: 0 0 16px var(--crt-glow), inset 0 0 12px var(--crt-wash);
}
.chat-user .rounded-3xl {
	box-shadow: inset 0 0 0 1px var(--crt-line);
}
#sidebar-chat-item.selected {
	background-color: var(--crt-wash);
	box-shadow: inset 2px 0 0 var(--crt-bright);
}
::selection {
	background-color: var(--crt-line);
}
html {
	scrollbar-color: var(--crt-line) transparent;
}

/* Rosé Pine: the Rosé Pine palette (main in dark modes, Dawn in light) laid onto Open WebUI's gray scale, with its accents on replies, the input and selection. Fixed colors; pairs with the Rosé Pine theme or any plain one. */
body {
	/* Dawn. Set on body so it overrides the theme palette for everything inside, menus included. */
	--color-white: #faf4ed;
	--color-gray-50: #fffaf3;
	--color-gray-100: #f2e9e1;
	--color-gray-200: #dfdad9;
	--color-gray-300: #cecacd;
	--color-gray-400: #9893a5;
	--color-gray-500: #9893a5;
	--color-gray-600: #797593;
	--color-gray-700: #575279;
	--color-gray-800: #575279;
	--color-gray-850: #575279;
	--color-gray-900: #575279;
	--color-gray-950: #464261;
	--rp-text: #575279; --rp-subtle: #797593; --rp-muted: #9893a5; --rp-hl: #dfdad9; --rp-overlay: #f2e9e1;
	--rp-love: #b4637a; --rp-gold: #ea9d34; --rp-rose: #d7827e; --rp-bold: #b4637a;
	--rp-pine: #286983; --rp-foam: #56949f; --rp-iris: #907aa9;
}
html.dark body {
	--color-white: #ffffff;
	--color-gray-50: #e0def4;
	--color-gray-100: #e0def4;
	--color-gray-200: #e0def4;
	--color-gray-300: #908caa;
	--color-gray-400: #908caa;
	--color-gray-500: #6e6a86;
	--color-gray-600: #6e6a86;
	--color-gray-700: #524f67;
	--color-gray-800: #403d52;
	--color-gray-850: #26233a;
	--color-gray-900: #191724;
	--color-gray-950: #1f1d2e;
	--rp-text: #e0def4; --rp-subtle: #908caa; --rp-muted: #6e6a86; --rp-hl: #403d52; --rp-overlay: #26233a;
	--rp-love: #eb6f92; --rp-gold: #f6c177; --rp-rose: #ebbcba; --rp-bold: #ebbcba;
	--rp-pine: #31748f; --rp-foam: #9ccfd8; --rp-iris: #c4a7e7;
}

.markdown-prose {
	--tw-prose-body: var(--rp-text);
	--tw-prose-headings: var(--rp-iris);
	--tw-prose-bold: var(--rp-bold);
	--tw-prose-links: var(--rp-foam);
	--tw-prose-code: var(--rp-bold);
	--tw-prose-quotes: var(--rp-subtle);
	--tw-prose-quote-borders: var(--rp-hl);
	--tw-prose-bullets: var(--rp-muted);
	--tw-prose-counters: var(--rp-subtle);
	--tw-prose-hr: var(--rp-hl);
	--tw-prose-th-borders: var(--rp-hl);
	--tw-prose-td-borders: var(--rp-hl);
}
#message-input-container:focus-within {
	border-color: var(--rp-iris);
}
.chat-user .rounded-3xl {
	background-color: var(--rp-overlay) !important;
}
#sidebar-chat-item.selected {
	background-color: var(--rp-hl);
}
#send-message-button:enabled {
	background-color: var(--rp-pine);
	color: #fffaf3;
}
::selection {
	background-color: var(--rp-hl);
}
html {
	scrollbar-color: var(--rp-muted) transparent;
}

/* Tactical HUD: a glass sidebar and input with a targeting glow, accent headings and table rules, all from the palette. Pairs with the Tactical Liquid Grid Canvas FX. */
:root {
	--hud-accent: var(--color-gray-800);
	--hud-glass: color-mix(in oklab, var(--color-gray-50) 70%, transparent);
	--hud-line: color-mix(in oklab, var(--color-gray-600) 25%, transparent);
	--hud-glow: color-mix(in oklab, var(--color-gray-600) 40%, transparent);
	--hud-wash: color-mix(in oklab, var(--color-gray-500) 10%, transparent);
	--hud-fade: color-mix(in oklab, var(--color-gray-50) 80%, transparent);
}
html.dark {
	--hud-accent: var(--color-gray-200);
	--hud-glass: color-mix(in oklab, var(--color-gray-950) 75%, transparent);
	--hud-line: color-mix(in oklab, var(--color-gray-300) 20%, transparent);
	--hud-glow: color-mix(in oklab, var(--color-gray-300) 40%, transparent);
	--hud-wash: color-mix(in oklab, var(--color-gray-300) 8%, transparent);
	--hud-fade: color-mix(in oklab, var(--color-gray-950) 80%, transparent);
}

/* Glass panels. */
#sidebar {
	background-color: var(--hud-glass) !important;
	backdrop-filter: blur(14px) saturate(1.2);
	border-inline-end: 1px solid var(--hud-line);
}
#sidebar-chat-item.selected {
	background-color: var(--hud-wash);
	box-shadow: inset 2px 0 0 var(--hud-accent);
}
#navbar-bg-gradient-to-b {
	background-image: linear-gradient(to bottom, var(--hud-fade), transparent);
}
#message-input-container {
	background-color: var(--hud-glass) !important;
	border-color: var(--hud-line);
	backdrop-filter: blur(10px);
	transition: border-color 0.3s, box-shadow 0.3s;
}
#message-input-container:focus-within {
	border-color: var(--hud-glow);
	box-shadow: 0 0 20px var(--hud-wash), 0 0 0 1px var(--hud-line);
}
.chat-user .rounded-3xl {
	background-color: var(--hud-wash) !important;
	box-shadow: inset 0 0 0 1px var(--hud-line);
}
#send-message-button:enabled {
	box-shadow: 0 0 12px var(--hud-glow);
}

/* Readouts. */
.markdown-prose {
	--tw-prose-headings: var(--hud-accent);
	--tw-prose-links: var(--hud-accent);
	--tw-prose-hr: var(--hud-line);
	--tw-prose-th-borders: var(--hud-line);
	--tw-prose-td-borders: var(--hud-wash);
}
.markdown-prose th {
	background-color: var(--hud-wash);
}
.markdown-prose .codespan {
	color: var(--hud-accent);
	box-shadow: inset 0 0 0 1px var(--hud-line);
}
::selection {
	background-color: var(--hud-glow);
}
html {
	scrollbar-color: var(--hud-line) transparent;
}

/* Windows Hot Dog Stand: the Windows 3.1 scheme in fixed colors, a red sidebar on a mustard-yellow chat with black outlines and hard shadows, and a black-bun version for dark modes. Use it on a plain theme without Canvas FX. */
:root {
	--hd-page: #ffff00;
	--hd-ink: #000000;
	--hd-body: #000000;
	--hd-edge: #000000;
	--hd-shadow: #000000;
	--hd-field: #ffffff;
	--hd-red: #ff0000;
	font-family: "Courier New", Courier, monospace;
}
html.dark {
	--hd-page: #000000;
	--hd-ink: #ffff00;
	--hd-body: #e8e8e8;
	--hd-edge: #ff0000;
	--hd-shadow: #ffff00;
	--hd-field: #000000;
}

#chat-container {
	background-color: var(--hd-page);
}
#navbar-bg-gradient-to-b {
	background-image: linear-gradient(to bottom, var(--hd-page), transparent);
}

/* The sidebar's own grays become the scheme: red panel, black text, yellow hover (black, yellow and dark red in dark modes). */
#sidebar {
	--color-gray-50: #ff0000;
	--color-gray-100: #ffff00;
	--color-gray-400: #000000;
	--color-gray-500: #000000;
	--color-gray-600: #000000;
	--color-gray-700: #000000;
	--color-gray-800: #000000;
	--color-gray-900: #000000;
	border-inline-end: 2px solid var(--hd-edge);
}
html.dark #sidebar {
	--color-gray-950: #000000;
	--color-gray-900: #b00000;
	--color-gray-850: #b00000;
	--color-gray-100: #ffff00;
	--color-gray-200: #ffff00;
	--color-gray-300: #ffff00;
	--color-gray-400: #ffff00;
	--color-gray-500: #ffff00;
}
#sidebar-chat-item.selected {
	background-color: #ffff00;
	box-shadow: 2px 2px 0 #000000;
}
html.dark #sidebar-chat-item.selected {
	background-color: #ff0000;
	box-shadow: 2px 2px 0 #ffff00;
	color: #000000;
}

#message-input-container {
	background-color: var(--hd-field) !important;
	border: 2px solid var(--hd-edge);
	box-shadow: 3px 3px 0 var(--hd-shadow);
}
.chat-user .rounded-3xl {
	background-color: var(--hd-red) !important;
	box-shadow: 2px 2px 0 var(--hd-shadow);
}
.chat-user .markdown-prose {
	--tw-prose-body: #000000;
}
.markdown-prose {
	--tw-prose-body: var(--hd-body);
	--tw-prose-headings: var(--hd-ink);
	--tw-prose-bold: var(--hd-ink);
	--tw-prose-links: var(--hd-red);
}
#send-message-button:enabled {
	background-color: var(--hd-ink);
	color: var(--hd-page);
}
::selection {
	background-color: #000000;
	color: #ffff00;
}
